import java.lang.reflect.Constructor;
import java.util.*;

public class Main {
    interface Notifier { String send(String msg); }
    static class EmailNotifier implements Notifier {
        public String send(String msg) { return "email:" + msg; }
    }
    static class OrderService {
        private final Notifier notifier;               // final: cannot be half-built
        OrderService(Notifier notifier) { this.notifier = notifier; }
        String place(String item) { return notifier.send("order " + item); }
    }

    // A tiny "container": bean registry plus constructor injection by parameter type
    static Map<Class<?>, Object> beans = new HashMap<>();

    static <T> T create(Class<T> type) throws Exception {
        Constructor<?> c = type.getDeclaredConstructors()[0];
        Object[] args = new Object[c.getParameterCount()];
        for (int i = 0; i < args.length; i++) {
            args[i] = beans.get(c.getParameterTypes()[i]);   // the container finds the dependency
        }
        return type.cast(c.newInstance(args));
    }

    public static void main(String[] a) throws Exception {
        beans.put(Notifier.class, new EmailNotifier());
        OrderService prod = create(OrderService.class);
        System.out.println("container wired: " + prod.place("book"));

        // Test without any container: just pass a fake through the constructor
        OrderService test = new OrderService(msg -> "fake:" + msg);
        System.out.println("unit test:       " + test.place("book"));
    }
}

import java.util.function.Supplier;

public class Main {
    static int created = 0;
    static class Ticket {                                   // pretend: prototype scope
        final int id = ++created;
    }
    static class StaleSingleton {
        private final Ticket ticket;                        // injected once at startup
        StaleSingleton(Ticket t) { ticket = t; }
        int use() { return ticket.id; }
    }
    static class FreshSingleton {
        private final Supplier<Ticket> provider;            // like ObjectProvider<Ticket>
        FreshSingleton(Supplier<Ticket> p) { provider = p; }
        int use() { return provider.get().id; }             // asks the container each time
    }

    public static void main(String[] args) {
        StaleSingleton stale = new StaleSingleton(new Ticket());
        FreshSingleton fresh = new FreshSingleton(Ticket::new);
        for (int call = 1; call <= 3; call++) {
            System.out.println("call " + call + ": stale uses ticket " + stale.use()
                + ", fresh uses ticket " + fresh.use());
        }
        // Stale keeps ticket 1 forever; fresh gets a new one per call
    }
}

import java.lang.reflect.Proxy;

public class Main {
    interface Service {
        void outer();
        void inner();
    }
    static class ServiceImpl implements Service {
        public void outer() {
            System.out.println("  outer body, calling this.inner()");
            this.inner();                                   // self-invocation: skips the proxy
        }
        public void inner() { System.out.println("  inner body"); }
    }

    public static void main(String[] args) {
        Service target = new ServiceImpl();
        // JDK dynamic proxy: wraps every call that goes through it with "advice"
        Service proxy = (Service) Proxy.newProxyInstance(
            Main.class.getClassLoader(), new Class<?>[]{Service.class},
            (p, method, margs) -> {
                System.out.println("BEGIN tx for " + method.getName());
                Object r = method.invoke(target, margs);    // the real object is called here
                System.out.println("COMMIT tx for " + method.getName());
                return r;
            });

        System.out.println("call proxy.inner():");
        proxy.inner();
        System.out.println("call proxy.outer():");
        proxy.outer();   // only outer gets a transaction; the inner call is not advised
    }
}

import java.util.*;

public class Main {
    static class User { final int id; String email; User(int id, String e) { this.id = id; email = e; } }

    static Map<Integer, String> db = new HashMap<>(Map.of(1, "a@x.com", 2, "b@x.com"));
    static Map<Integer, User> managed = new HashMap<>();        // first-level cache
    static Map<Integer, String> snapshot = new HashMap<>();     // state when loaded
    static int selects = 0;

    static User find(int id) {
        if (!managed.containsKey(id)) {                         // only hits the "database" once
            selects++;
            managed.put(id, new User(id, db.get(id)));
            snapshot.put(id, db.get(id));
        }
        return managed.get(id);
    }

    static void flush() {                                       // dirty checking
        for (User u : managed.values()) {
            if (!u.email.equals(snapshot.get(u.id))) {
                System.out.println("UPDATE user SET email='" + u.email + "' WHERE id=" + u.id);
                db.put(u.id, u.email);
            }
        }
    }

    public static void main(String[] args) {
        User u1 = find(1), again = find(1), other = find(2);
        System.out.println("same instance: " + (u1 == again) + ", SELECTs: " + selects);
        u1.email = "new@x.com";                                 // no save() call at all
        flush();
        System.out.println("db now: " + new TreeMap<>(db));
    }
}

import java.util.*;

public class Main {
    static int queries = 0;
    static Map<Integer, String> authors = new LinkedHashMap<>();
    static Map<Integer, List<String>> booksByAuthor = new HashMap<>();

    static List<Integer> loadAuthors() { queries++; return new ArrayList<>(authors.keySet()); }
    static List<String> loadBooks(int authorId) {               // one query per author
        queries++;
        return booksByAuthor.get(authorId);
    }
    static Map<Integer, List<String>> loadBooksFor(List<Integer> ids) {   // like join fetch / IN (...)
        queries++;
        Map<Integer, List<String>> m = new HashMap<>();
        for (int id : ids) m.put(id, booksByAuthor.get(id));
        return m;
    }

    public static void main(String[] args) {
        for (int i = 1; i <= 5; i++) {
            authors.put(i, "author" + i);
            booksByAuthor.put(i, List.of("book" + i + "a", "book" + i + "b"));
        }
        // Lazy loading: 1 query for authors + N queries inside the loop
        queries = 0;
        for (int id : loadAuthors()) loadBooks(id);
        System.out.println("N+1 style: " + queries + " queries for 5 authors");

        // Batched: 1 query for authors + 1 for all their books
        queries = 0;
        List<Integer> ids = loadAuthors();
        Map<Integer, List<String>> books = loadBooksFor(ids);
        System.out.println("fetched:   " + queries + " queries, " + books.size() + " authors loaded");
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Semaphore pool = new Semaphore(2);                  // pool of 2 connections
        CyclicBarrier bothHoldOne = new CyclicBarrier(2);
        CyclicBarrier bothTried = new CyclicBarrier(2);
        ExecutorService ex = Executors.newFixedThreadPool(2);
        Callable<String> request = () -> {
            pool.acquire();                                 // outer transaction takes a connection
            try {
                bothHoldOne.await();                        // make both requests reach the inner call together
                // inner REQUIRES_NEW needs a second connection while the first is still held
                boolean ok = pool.tryAcquire(300, TimeUnit.MILLISECONDS);
                bothTried.await();                          // keep holding the first connection meanwhile
                if (ok) pool.release();
                return ok ? "inner got a connection" : "inner timed out waiting for a connection";
            } finally {
                pool.release();
            }
        };
        Future<String> f1 = ex.submit(request), f2 = ex.submit(request);
        System.out.println("pool size 2, 2 concurrent requests, each needing 2 connections");
        System.out.println("request 1: " + f1.get());
        System.out.println("request 2: " + f2.get());
        ex.shutdown();
    }
}
